/// <summary>
/// MPJ_3171_AP_PricingConditions - KScerri - 26/03/2021
/// Find method to find record from table METPurchConditionType
/// </summary>
/// <param name = "_conditionTypeId">condition type id</param>
/// <param name = "_forUpdate">for update</param>
/// <returns>The table record</returns>
static METPurchConditionType find(METPurchConditionTypeId _conditionTypeId, boolean _forUpdate = false)
{
    METPurchConditionType    purchConditionType;
    
    if (_conditionTypeId)
    {
        purchConditionType.selectForUpdate(_forUpdate);
      
        select firstonly purchConditionType
                 where purchConditionType.ConditionTypeId == _conditionTypeId;
    }
    
    return purchConditionType;
}

/// <summary>
/// MPJ_3171_AP_PricingConditions - KScerri - 26/03/2021
/// Exists method for table METPurchConditionType.
/// </summary>
/// <param name = "_conditionTypeId">condition type id</param>
/// <returns>check if exitist</returns>
static boolean exist(METPurchConditionTypeId _conditionTypeId)
{
    return _conditionTypeId  &&
           (select firstonly RecId from METPurchConditionType
                 where METPurchConditionType.ConditionTypeId == _conditionTypeId).RecId != 0;
}

