    /// <summary>
    /// MPJ_3171_AP_PricingConditions - KScerri - 26/03/2021
    /// CheckExist method for table METPurchConditionType.
    /// </summary>
    /// <param name = "_conditionTypeId">condition type id</param>
    /// <returns>check exits</returns>
    public static boolean checkExist(METPurchConditionTypeId _conditionTypeId)
    {
        boolean ret = true;
 
        if (!METPayPricingCondition::exist(_conditionTypeId))
        {
            ret = checkFailed(strfmt(METPayPricingCondition::txtNotExist(),
                                 _conditionTypeId,
                                 fieldId2PName(tableNum(METPurchConditionType), fieldNum(METPurchConditionType, ConditionTypeId)),
                                 tableId2PName(tableNum(METPurchConditionType))));
        }

        return ret;
    }
